import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';import syncFs from 'node:fs';import {parseEnv} from 'node:util';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import {SESv2Client,GetAccountCommand,GetSuppressedDestinationCommand,SendEmailCommand} from '@aws-sdk/client-sesv2';
for(const[k,v]of Object.entries(parseEnv(syncFs.readFileSync('.env.ses.local','utf8'))))if(k.startsWith('AWS_')||k.startsWith('SES_'))process.env[k]=v;
const{db,base,headers}=await import('./reply-runtime-20261015.mjs');const{api}=await import('./gta-email-recovery-runtime.mjs');const{reserveAction}=await import('../lib/partnership-core/reserve.mjs');const dir='artifacts/replies-stagers-20261019';const plans=JSON.parse(await fs.readFile(dir+'/stager-send-plan.json'));const preflight=JSON.parse(await fs.readFile(dir+'/stager-preflight.json'));const norm=v=>String(v||'').replace(/\D/g,'').slice(-10);const results=[];
for(const p of plans){const file=dir+'/stager-receipt-'+p.id+'.json';try{
 try{await fs.access(file);results.push({name:p.name,state:'existing_receipt_no_retry'});continue;}catch(e){if(e.code!=='ENOENT')throw e;}
 const ctx=preflight.rows.find(r=>r.contact.id===p.id);const peers=(await db('market_contacts',{phone:'ilike.*'+norm(p.phone).slice(-4)+'*'})).filter(c=>norm(c.phone)===norm(p.phone));assert.deepEqual(peers.map(c=>c.id).sort(),ctx.peers.map(r=>r.contact.id).sort());
 for(const c of peers){assert(!c.do_not_contact&&!c.cross_channel_suppressed_at&&!['dnc','closed_lost'].includes(c.stage)&&!['opted_out','rejected'].includes(c.decision),'suppressed');const[last]=await db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.desc,id.desc',limit:'1'});assert.equal(last?.id,ctx.peers.find(r=>r.contact.id===c.id).thread.at(-1)?.id,'Changed partnership thread');}
 const phone='+1'+norm(p.phone);const sms=await db('sms_messages',{or:`(from_number.eq.${phone},to_number.eq.${phone})`,order:'created_at.desc',limit:'1'});assert.equal(sms[0]?.id,ctx.sms[0]?.id,'Changed Sales SMS');const calls=await db('call_recordings',{phone_number:'eq.'+phone,order:'created_at.desc',limit:'1'});assert.equal(calls[0]?.recording_sid,ctx.calls[0]?.recording_sid,'Changed call history');
 for(const url of p.media_urls){const r=await fetch(url);assert(r.ok&&r.headers.get('content-type')?.includes('image/'),'Card unavailable');}
 let result,touch;
 if(p.channel==='email'){
  const c=peers.find(c=>c.id===p.id);assert.equal(c.email?.toLowerCase(),p.email.toLowerCase());const em=await db('market_contacts',{email:'ilike.'+p.email});assert(em.every(x=>!x.do_not_contact&&!x.cross_channel_suppressed_at&&!x.email_unsubscribed_at&&!['bounced','complained','unsubscribed'].includes(x.email_status)));
  const ses=new SESv2Client({region:process.env.AWS_REGION||'us-east-2',maxAttempts:1});const health=await ses.send(new GetAccountCommand({}));assert(health.SendingEnabled&&health.ProductionAccessEnabled&&health.EnforcementStatus==='HEALTHY');try{await ses.send(new GetSuppressedDestinationCommand({EmailAddress:p.email}));throw Error('SES suppressed');}catch(e){if(e.name!=='NotFoundException')throw e;}
  await fs.writeFile(file,JSON.stringify({state:'reserved_no_blind_retry',at:new Date().toISOString(),plan:p},null,2),{flag:'wx'});const sender='John | Saturn Star Movers <john@saturnstarmovers.ca>';const key='stager-contextual-followup-20261019:'+p.id;await reserveAction({url:base,headers,contactId:p.id,channel:'email',kind:'reply',key,content:p.subject+'\n'+p.body,sender,emailProvider:'ses'});const h=createHash('sha256').update(key).digest('hex');const tid=[h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20,32)].join('-');const metadata={source:'owner_requested_staging_followup',from:sender,to:p.email,subject:p.subject,reply_to:'business@starmovers.ca',provider:'ses',delivery_state:'reserved'};await db('market_touches',{},'POST',{id:tid,contact_id:p.id,channel:'email',direction:'outbound',notes:'Subject: '+p.subject+'\n\n'+p.body,metadata});const sent=await ses.send(new SendEmailCommand({FromEmailAddress:sender,ReplyToAddresses:['business@starmovers.ca'],Destination:{ToAddresses:[p.email]},ConfigurationSetName:process.env.AWS_SES_CONFIGURATION_SET||undefined,EmailTags:[{Name:'contact_id',Value:p.id}],Content:{Simple:{Subject:{Data:p.subject,Charset:'UTF-8'},Body:{Text:{Data:p.body,Charset:'UTF-8'}}}}}));assert(sent.MessageId);result={messageId:sent.MessageId};await fs.writeFile(file,JSON.stringify({state:'accepted',at:new Date().toISOString(),plan:p,result},null,2));await db('market_touches',{id:'eq.'+tid},'PATCH',{metadata:{...metadata,delivery_state:'accepted',provider_message_id:sent.MessageId}});[touch]=await db('market_touches',{id:'eq.'+tid});assert.equal(touch.metadata.provider_message_id,sent.MessageId);await db('market_contacts',{id:'eq.'+p.id},'PATCH',{preferred_channel:'email',email_last_sent_at:new Date().toISOString(),last_touch_at:new Date().toISOString()});
 }else{
  await fs.writeFile(file,JSON.stringify({state:'reserved_no_blind_retry',at:new Date().toISOString(),plan:p},null,2),{flag:'wx'});result=await api('/api/marketing/contacts/'+p.id+'/send-reply',{body:p.body,from_number:'+12268870667',media_urls:p.media_urls});await fs.writeFile(file,JSON.stringify({state:'provider_response',at:new Date().toISOString(),plan:p,result},null,2));assert(result.sid);const t=await db('market_touches',{contact_id:'eq.'+p.id,direction:'eq.outbound',order:'created_at.desc',limit:'5'});touch=t.find(t=>[t.metadata?.twilioSid,t.metadata?.provider_message_id].includes(result.sid));assert(touch,'No CRM receipt');
 }
 for(const c of peers)await db('market_contacts',{id:'eq.'+c.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'One owner-authorized staging follow-up; await response',next_follow_up:null});await fs.writeFile(file,JSON.stringify({state:'accepted_crm_verified',at:new Date().toISOString(),plan:p,result,touch_id:touch.id},null,2));results.push({name:p.name,channel:p.channel,state:'accepted_crm_verified'});console.log(JSON.stringify(results.at(-1)));
 }catch(e){results.push({name:p.name,state:'held_no_blind_retry',error:e.message});console.log(JSON.stringify(results.at(-1)));}await fs.writeFile(dir+'/stager-results.json',JSON.stringify(results,null,2));}
